patch.unified_diff:
===================================================================
--- a/src/tools.ts
+++ b/src/tools.ts
@@ -1,20 +1,20 @@
 import { z } from "zod";

 export const listIssuesTool = {
   name: "list_issues",
-  description: "List issues.",
+  description: "List issues, optionally filtered by status and assignee. Use to browse or enumerate issues; use search_issues to find issues by text in the title or body, and get_issue for one known ID. Returns at most 50 issues unless limit is set. Comments are included by default; set include_comments to false for smaller responses.",
   params: {
     status: z.string().optional(),
     assignee: z.string().optional(),
-    include_comments: z.boolean().optional(),
+    include_comments: z.boolean().optional().describe("Whether to include each issue's comments. Defaults to true when omitted; set false to get summaries without comments and reduce response size."),
     limit: z.number().optional(),
   },
 };

 export const searchIssuesTool = {
   name: "search_issues",
-  description: "Search issues.",
+  description: "Search issues by case-insensitive text match on title or body. Use when you have keywords; use list_issues to filter by status or assignee, and get_issue for one known ID. Has no status, assignee or limit filter, and returns all matches. Comments are included by default; set include_comments to false for smaller responses.",
   params: {
     query: z.string(),
     include_comments: z.boolean().optional(),
   },
@@ -23,7 +23,7 @@
 export const getIssueTool = {
   name: "get_issue",
   description: "Get a single issue by its ID, for example TRK-117. Returns the title, status, assignee, body and full comment thread.",
   params: {
-    id: z.string(),
+    id: z.string().describe("Exact issue ID, as in the id field of an issue (e.g. TRK-117). Matching is exact; an unknown ID returns an \"Issue not found\" error."),
   },
 };
